	LOC_BGD_OPT_MASQUER_AVANCEES = { en_US = "Hide advanced options", fr_FR = "Masquer les options avancées", de_DE = "Erweiterte Optionen ausblenden", es_ES = "Ocultar las opciones avanzadas", it_IT = "Nascondi le opzioni avanzate", ja_JP = "詳細オプションを隠す", ko_KR = "고급 옵션 숨기기", pl_PL = "Ukryj opcje zaawansowane", pt_BR = "Ocultar as opções avançadas", ru_RU = "Скрыть дополнительные настройки", zh_Hans_CN = "隐藏高级选项" },
	LOC_BGD_OPT_MODE_AIDE = { en_US = "During a cascade of war declarations, city and diplomacy data are refreshed only once, at the end: over 2 s saved on a heavy turn. Does not change the game: safe in multiplayer, even against players without the proxy.", fr_FR = "Pendant une cascade de déclarations de guerre, les données de villes et de diplomatie ne sont rafraîchies qu'une fois, à la fin : plus de 2 s gagnées sur un gros passage de tour. Ne change rien à la partie : sans risque en multijoueur, même face à des joueurs sans proxy.", de_DE = "Während einer Kaskade von Kriegserklärungen werden Stadt- und Diplomatiedaten nur einmal am Ende aktualisiert: über 2 s Ersparnis bei einer schweren Runde. Ändert nichts am Spiel: sicher im Mehrspielermodus, auch gegen Spieler ohne Proxy.", es_ES = "Durante una cascada de declaraciones de guerra, los datos de ciudades y de diplomacia solo se actualizan una vez, al final: más de 2 s ahorrados en un turno pesado. No cambia nada de la partida: seguro en multijugador, incluso contra jugadores sin el proxy.", it_IT = "Durante una cascata di dichiarazioni di guerra, i dati delle città e della diplomazia vengono aggiornati una sola volta, alla fine: oltre 2 s risparmiati in un turno pesante. Non cambia nulla della partita: sicuro in multigiocatore, anche contro giocatori senza il proxy.", ja_JP = "宣戦布告が連鎖する間、都市と外交のデータは最後に一度だけ更新されます。重いターンで2秒以上短縮されます。ゲーム内容は変わらないため、プロキシを持たないプレイヤーとのマルチプレイでも安全です。", ko_KR = "연쇄 선전포고가 일어나는 동안 도시와 외교 데이터를 마지막에 한 번만 갱신합니다. 무거운 턴에서 2초 이상 단축됩니다. 게임 내용은 바뀌지 않으므로, 프록시가 없는 플레이어와의 멀티플레이에서도 안전합니다.", pl_PL = "Podczas kaskady wypowiedzeń wojny dane miast i dyplomacji są odświeżane tylko raz, na końcu: ponad 2 s oszczędności w ciężkiej turze. Nie zmienia niczego w rozgrywce: bezpieczne w trybie wieloosobowym, także z graczami bez proxy.", pt_BR = "Durante uma cascata de declarações de guerra, os dados de cidades e de diplomacia são atualizados só uma vez, no final: mais de 2 s economizados num turno pesado. Não muda nada na partida: seguro no multijogador, mesmo contra jogadores sem o proxy.", ru_RU = "Во время каскада объявлений войны данные городов и дипломатии обновляются только один раз, в конце: более 2 с экономии на тяжёлом ходу. Ничего не меняет в партии: безопасно в сетевой игре, даже с игроками без прокси.", zh_Hans_CN = "在连锁宣战期间，城市和外交数据只在最后刷新一次：繁重的回合可节省 2 秒以上。不改变游戏内容：在多人游戏中安全，即使对方没有代理。" },
	LOC_BGD_OPT_MODE_NOM = { en_US = "Batched city updates", fr_FR = "Regroupement des mises à jour de villes", de_DE = "Gebündelte Stadt-Aktualisierungen", es_ES = "Actualizaciones de ciudades agrupadas", it_IT = "Aggiornamenti delle città raggruppati", ja_JP = "都市の更新をまとめる", ko_KR = "도시 갱신 묶기", pl_PL = "Zgrupowane aktualizacje miast", pt_BR = "Atualizações de cidades agrupadas", ru_RU = "Объединённые обновления городов", zh_Hans_CN = "合并城市更新" },
	LOC_BGD_OPT_NON_ENREGISTRES = { en_US = "Settings not saved: {1}", fr_FR = "Réglages non enregistrés : {1}", de_DE = "Einstellungen nicht gespeichert: {1}", es_ES = "Ajustes no guardados: {1}", it_IT = "Impostazioni non salvate: {1}", ja_JP = "設定を保存できませんでした: {1}", ko_KR = "설정을 저장하지 못했습니다: {1}", pl_PL = "Ustawienia nie zostały zapisane: {1}", pt_BR = "Configurações não salvas: {1}", ru_RU = "Настройки не сохранены: {1}", zh_Hans_CN = "设置未保存：{1}" },
	LOC_BGD_OPT_NON_INSTALLE = { en_US = "GameCore proxy not installed: these settings will only take effect once it is installed.", fr_FR = "Proxy de GameCore non installé : ces réglages n'auront d'effet qu'une fois installé.", de_DE = "GameCore-Proxy nicht installiert: Diese Einstellungen wirken erst, wenn er installiert ist.", es_ES = "Proxy de GameCore no instalado: estos ajustes solo surtirán efecto una vez instalado.", it_IT = "Proxy di GameCore non installato: queste impostazioni avranno effetto solo una volta installato.", ja_JP = "GameCore プロキシがインストールされていません。これらの設定はインストール後に有効になります。", ko_KR = "GameCore 프록시가 설치되어 있지 않습니다. 이 설정은 설치한 뒤에 적용됩니다.", pl_PL = "Proxy GameCore nie jest zainstalowane: te ustawienia zaczną działać dopiero po jego instalacji.", pt_BR = "Proxy do GameCore não instalado: estas configurações só terão efeito depois que ele for instalado.", ru_RU = "Прокси GameCore не установлен: эти настройки вступят в силу только после его установки.", zh_Hans_CN = "GameCore 代理未安装：这些设置要在安装后才会生效。" },
	LOC_BGD_OPT_PORTEE_AIDE = { en_US = "\"Every game message\" also batches refreshes outside of wars (governors, resources, deals). The interface may then show city data a moment late.", fr_FR = "« Chaque message du jeu » regroupe aussi les rafraîchissements hors guerre (gouverneurs, ressources, accords). L'interface peut alors montrer une donnée de ville en retard d'un instant.", de_DE = "„Jede Spielnachricht“ bündelt auch Aktualisierungen außerhalb von Kriegen (Gouverneure, Ressourcen, Abkommen). Die Oberfläche kann Stadtdaten dann einen Moment verzögert anzeigen.", es_ES = "«Cada mensaje del juego» agrupa también las actualizaciones fuera de las guerras (gobernadores, recursos, acuerdos). La interfaz puede mostrar entonces un dato de ciudad con un instante de retraso.", it_IT = "\"Ogni messaggio del gioco\" raggruppa anche gli aggiornamenti fuori dalle guerre (governatori, risorse, accordi). L'interfaccia può allora mostrare un dato di città con un attimo di ritardo.", ja_JP = "「ゲームのすべてのメッセージ」を選ぶと、戦争以外の更新 (総督、資源、取引) もまとめます。その場合、インターフェースの都市データが一瞬遅れて表示されることがあります。", ko_KR = "\"게임의 모든 메시지\"는 전쟁 외의 갱신(총독, 자원, 거래)도 묶습니다. 이 경우 인터페이스의 도시 정보가 잠시 늦게 표시될 수 있습니다.", pl_PL = "„Każdy komunikat gry” grupuje także odświeżenia poza wojnami (gubernatorzy, zasoby, umowy). Interfejs może wtedy pokazać dane miasta z chwilowym opóźnieniem.", pt_BR = "\"Cada mensagem do jogo\" agrupa também as atualizações fora das guerras (governadores, recursos, acordos). A interface pode então mostrar um dado de cidade com um instante de atraso.", ru_RU = "«Каждое сообщение игры» объединяет и обновления вне войн (губернаторы, ресурсы, сделки). Тогда интерфейс может показывать данные города с небольшой задержкой.", zh_Hans_CN = "“每条游戏消息”也会合并战争以外的刷新（总督、资源、交易）。此时界面显示的城市数据可能会稍有延迟。" },
	LOC_BGD_OPT_PORTEE_NOM = { en_US = "Batching scope", fr_FR = "Portée du regroupement", de_DE = "Umfang der Bündelung", es_ES = "Alcance de la agrupación", it_IT = "Portata del raggruppamento", ja_JP = "まとめる範囲", ko_KR = "묶는 범위", pl_PL = "Zakres grupowania", pt_BR = "Alcance do agrupamento", ru_RU = "Охват объединения", zh_Hans_CN = "合并范围" },
	LOC_BGD_OPT_PROFIL_ZONES_AIDE = { en_US = "Records the duration of every zone the game times (frame, interface, scripts, events) to %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, for performance analysis. About 1 MB per second of play. Takes effect the next time the game starts.", fr_FR = "Note la durée de chaque zone chronométrée par le jeu (image, interface, scripts, événements) dans %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, pour l'analyse des performances. Environ 1 Mo par seconde de jeu. Prend effet au prochain lancement du jeu.", de_DE = "Zeichnet die Dauer jeder vom Spiel gemessenen Zone (Bild, Oberfläche, Skripte, Ereignisse) in %LOCALAPPDATA%\\Civ6RolloverProxy\\zones auf, für die Leistungsanalyse. Etwa 1 MB pro Sekunde Spielzeit. Wirkt beim nächsten Spielstart.", es_ES = "Registra la duración de cada zona que cronometra el juego (imagen, interfaz, scripts, eventos) en %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, para el análisis de rendimiento. Unos 1 MB por segundo de juego. Surte efecto la próxima vez que se inicie el juego.", it_IT = "Registra la durata di ogni zona cronometrata dal gioco (immagine, interfaccia, script, eventi) in %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, per l'analisi delle prestazioni. Circa 1 MB per secondo di gioco. Ha effetto al prossimo avvio del gioco.", ja_JP = "ゲームが計測する各区間 (フレーム、インターフェース、スクリプト、イベント) の所要時間を、パフォーマンス分析のため %LOCALAPPDATA%\\Civ6RolloverProxy\\zones に記録します。プレイ1秒あたり約1MB。次回のゲーム起動時から有効です。", ko_KR = "게임이 측정하는 각 구간(프레임, 인터페이스, 스크립트, 이벤트)의 시간을 성능 분석을 위해 %LOCALAPPDATA%\\Civ6RolloverProxy\\zones에 기록합니다. 플레이 1초당 약 1MB입니다. 다음에 게임을 시작할 때부터 적용됩니다.", pl_PL = "Zapisuje czas trwania każdej strefy mierzonej przez grę (klatka, interfejs, skrypty, zdarzenia) w %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, do analizy wydajności. Około 1 MB na sekundę gry. Działa od następnego uruchomienia gry.", pt_BR = "Registra a duração de cada zona cronometrada pelo jogo (quadro, interface, scripts, eventos) em %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, para a análise de desempenho. Cerca de 1 MB por segundo de jogo. Vale a partir da próxima vez que o jogo for iniciado.", ru_RU = "Записывает длительность каждой зоны, которую замеряет игра (кадр, интерфейс, скрипты, события), в %LOCALAPPDATA%\\Civ6RolloverProxy\\zones для анализа производительности. Около 1 МБ на секунду игры. Действует со следующего запуска игры.", zh_Hans_CN = "将游戏计时的每个区段（帧、界面、脚本、事件）的耗时记录到 %LOCALAPPDATA%\\Civ6RolloverProxy\\zones，用于性能分析。每秒游戏约 1 MB。下次启动游戏时生效。" },
	LOC_BGD_OPT_PROFIL_ZONES_NOM = { en_US = "Profile the game's timed zones", fr_FR = "Profil des zones de l'exe", de_DE = "Zeitzonen des Spiels aufzeichnen", es_ES = "Perfil de las zonas cronometradas del juego", it_IT = "Profilo delle zone cronometrate del gioco", ja_JP = "ゲームの計測区間のプロファイル", ko_KR = "게임 측정 구간 프로필", pl_PL = "Profil mierzonych stref gry", pt_BR = "Perfil das zonas cronometradas do jogo", ru_RU = "Профиль замеряемых зон игры", zh_Hans_CN = "游戏计时区段分析" },
	LOC_BGD_OPT_REINIT_AIDE = { en_US = "Restores every BetterGameExperience setting to its default value.", fr_FR = "Remet tous les réglages de BetterGameExperience à leur valeur par défaut.", de_DE = "Setzt alle Einstellungen von BetterGameExperience auf ihren Standardwert zurück.", es_ES = "Devuelve todos los ajustes de BetterGameExperience a su valor predeterminado.", it_IT = "Riporta tutte le impostazioni di BetterGameExperience al loro valore predefinito.", ja_JP = "BetterGameExperience のすべての設定を既定値に戻します。", ko_KR = "BetterGameExperience의 모든 설정을 기본값으로 되돌립니다.", pl_PL = "Przywraca wszystkie ustawienia BetterGameExperience do wartości domyślnych.", pt_BR = "Restaura todos os ajustes do BetterGameExperience para o valor padrão.", ru_RU = "Возвращает все настройки BetterGameExperience к значениям по умолчанию.", zh_Hans_CN = "将 BetterGameExperience 的所有设置恢复为默认值。" },
