	LOC_BGD_OPT_TITRE_MODS = { en_US = "Built-in interface mods", fr_FR = "Mods d'interface intégrés", de_DE = "Integrierte Oberflächen-Mods", es_ES = "Mods de interfaz integrados", it_IT = "Mod dell'interfaccia integrate", ja_JP = "組み込みインターフェースMOD", ko_KR = "내장 인터페이스 모드", pl_PL = "Wbudowane mody interfejsu", pt_BR = "Mods de interface integrados", ru_RU = "Встроенные моды интерфейса", zh_Hans_CN = "内置界面模组" },
	LOC_BGD_OPT_TITRE_PERFORMANCES = { en_US = "Turn processing performance", fr_FR = "Performances du passage de tour", de_DE = "Leistung der Rundenberechnung", es_ES = "Rendimiento del cambio de turno", it_IT = "Prestazioni del cambio di turno", ja_JP = "ターン処理のパフォーマンス", ko_KR = "턴 처리 성능", pl_PL = "Wydajność przetwarzania tury", pt_BR = "Desempenho da passagem de turno", ru_RU = "Скорость смены хода", zh_Hans_CN = "回合处理性能" },
	LOC_BGD_OPT_TOURS_PRODUCTION_AIDE = { en_US = "The displayed number of turns includes government bonuses (Fascism, Autocracy, Merchant Republic), like the actual production. Display only.", fr_FR = "Le nombre de tours affiché tient compte des bonus de gouvernement (fascisme, autocratie, république maritime), comme la production réelle. Affichage seulement.", de_DE = "Die angezeigte Rundenzahl berücksichtigt die Regierungsboni (Faschismus, Autokratie, Handelsrepublik), wie die tatsächliche Produktion. Nur Anzeige.", es_ES = "El número de turnos mostrado tiene en cuenta las bonificaciones de gobierno (fascismo, autocracia, república mercantil), como la producción real. Solo visualización.", it_IT = "Il numero di turni mostrato tiene conto dei bonus di governo (fascismo, autocrazia, repubblica mercantile), come la produzione reale. Solo visualizzazione.", ja_JP = "表示されるターン数に、実際の生産と同じく政府のボーナス (ファシズム、独裁政治、商業共和制) を反映します。表示のみ。", ko_KR = "표시되는 턴 수에 실제 생산처럼 정부 보너스(파시즘, 전제정치, 상인 공화제)를 반영합니다. 표시만 바뀝니다.", pl_PL = "Wyświetlana liczba tur uwzględnia premie ustroju (faszyzm, autokracja, republika kupiecka), tak jak rzeczywista produkcja. Tylko wyświetlanie.", pt_BR = "O número de turnos exibido leva em conta os bônus de governo (fascismo, autocracia, república mercante), como a produção real. Apenas exibição.", ru_RU = "Показанное число ходов учитывает бонусы формы правления (фашизм, автократия, торговая республика), как и реальное производство. Только отображение.", zh_Hans_CN = "显示的回合数会像实际生产一样计入政体加成（法西斯主义、独裁统治、商人共和国）。仅影响显示。" },
	LOC_BGD_OPT_TOURS_PRODUCTION_NOM = { en_US = "Fixed production turn counter", fr_FR = "Compteur de tours de production corrigé", de_DE = "Korrigierter Produktions-Rundenzähler", es_ES = "Contador de turnos de producción corregido", it_IT = "Contatore dei turni di produzione corretto", ja_JP = "生産ターン数の表示を修正", ko_KR = "생산 턴 수 표시 수정", pl_PL = "Poprawiony licznik tur produkcji", pt_BR = "Contador de turnos de produção corrigido", ru_RU = "Исправленный счётчик ходов производства", zh_Hans_CN = "修正生产回合数" },
	LOC_BGD_OPT_UI_BANDEAU_AIDE = { en_US = "Based on TopPanel Extension Pro (号码菌 / Azukii). Food, production, population, average amenities per city and luxury resources in the top panel, with per-city details; teammates' resources. Replaces the mod if it is active. Without the mod, Better Spectator Mod's top panel is kept.", fr_FR = "D'après TopPanel Extension Pro (号码菌 / Azukii). Nourriture, production, population, activités moyennes par ville et ressources de luxe dans le bandeau, avec le détail par ville ; ressources des coéquipiers. Remplace le mod s'il est actif. Sans le mod, le bandeau de Better Spectator Mod est gardé.", de_DE = "Nach TopPanel Extension Pro (号码菌 / Azukii). Nahrung, Produktion, Bevölkerung, durchschnittliche Annehmlichkeiten pro Stadt und Luxusressourcen in der oberen Leiste, mit Details pro Stadt; Ressourcen der Teamkameraden. Ersetzt den Mod, wenn er aktiv ist. Ohne den Mod bleibt die obere Leiste von Better Spectator Mod erhalten.", es_ES = "Basado en TopPanel Extension Pro (号码菌 / Azukii). Comida, producción, población, servicios medios por ciudad y recursos de lujo en la barra superior, con el detalle por ciudad; recursos de los compañeros de equipo. Sustituye al mod si está activo. Sin el mod, se conserva la barra superior de Better Spectator Mod.", it_IT = "Basato su TopPanel Extension Pro (号码菌 / Azukii). Cibo, produzione, popolazione, attrattiva media per città e risorse di lusso nella barra superiore, con il dettaglio per città; risorse dei compagni di squadra. Sostituisce la mod se è attiva. Senza la mod, la barra superiore di Better Spectator Mod viene mantenuta.", ja_JP = "TopPanel Extension Pro (号码菌 / Azukii) に基づきます。食料、生産力、人口、都市あたりの平均快適性、高級資源を都市ごとの詳細とともに上部バーに表示し、チームメイトの資源も表示します。MOD が有効な場合はそれに置き換わります。MOD がない場合は Better Spectator Mod の上部バーが維持されます。", ko_KR = "TopPanel Extension Pro(号码菌 / Azukii) 기반. 식량, 생산력, 인구, 도시당 평균 쾌적도, 사치 자원을 도시별 상세 정보와 함께 상단 바에 표시하고, 팀원의 자원도 보여 줍니다. 모드가 켜져 있으면 모드를 대체합니다. 모드가 없으면 Better Spectator Mod의 상단 바가 유지됩니다.", pl_PL = "Na podstawie TopPanel Extension Pro (号码菌 / Azukii). Żywność, produkcja, populacja, średnie udogodnienia na miasto i zasoby luksusowe w górnym pasku, ze szczegółami dla każdego miasta; zasoby sojuszników z drużyny. Zastępuje moda, jeśli jest aktywny. Bez moda zachowany jest górny pasek Better Spectator Mod.", pt_BR = "Baseado em TopPanel Extension Pro (号码菌 / Azukii). Comida, produção, população, média de serviços por cidade e recursos de luxo na barra superior, com o detalhe por cidade; recursos dos colegas de equipe. Substitui o mod se ele estiver ativo. Sem o mod, a barra superior do Better Spectator Mod é mantida.", ru_RU = "На основе TopPanel Extension Pro (号码菌 / Azukii). Пища, производство, население, среднее довольство на город и ресурсы роскоши на верхней панели, с подробностями по городам; ресурсы союзников по команде. Заменяет мод, если он включён. Без мода сохраняется верхняя панель Better Spectator Mod.", zh_Hans_CN = "基于 TopPanel Extension Pro（号码菌 / Azukii）。在顶部栏显示食物、生产力、人口、每座城市的平均宜居度和奢侈品资源，并附各城市详情；还显示队友的资源。如果该模组已启用，则取代它。没有该模组时，保留 Better Spectator Mod 的顶部栏。" },
	LOC_BGD_OPT_UI_BANDEAU_NOM = { en_US = "Extended top panel", fr_FR = "Bandeau du haut étendu", de_DE = "Erweiterte obere Leiste", es_ES = "Barra superior ampliada", it_IT = "Barra superiore estesa", ja_JP = "拡張された上部バー", ko_KR = "확장된 상단 바", pl_PL = "Rozszerzony górny pasek", pt_BR = "Barra superior ampliada", ru_RU = "Расширенная верхняя панель", zh_Hans_CN = "扩展顶部栏" },
	LOC_BGD_OPT_UI_BOUTONS_AIDE = { en_US = "City and encampment attack buttons, and silo nuclear strike buttons, are drawn above unit flags, where they stay clickable.", fr_FR = "Les boutons d'attaque des villes et des campements, et ceux de frappe nucléaire des silos, passent au-dessus des drapeaux d'unités, où ils restent cliquables.", de_DE = "Die Angriffsschaltflächen von Städten und Lagern sowie die Atomschlag-Schaltflächen der Silos werden über den Einheitenflaggen gezeichnet, wo sie anklickbar bleiben.", es_ES = "Los botones de ataque de ciudades y campamentos, y los de ataque nuclear de los silos, se dibujan sobre las banderas de unidades, donde se pueden pulsar.", it_IT = "I pulsanti di attacco delle città e degli accampamenti, e quelli di attacco nucleare dei silos, vengono disegnati sopra le bandiere delle unità, dove restano cliccabili.", ja_JP = "都市と兵営の攻撃ボタン、およびサイロの核攻撃ボタンをユニットの旗より手前に表示し、クリックできるようにします。", ko_KR = "도시와 주둔지의 공격 버튼, 사일로의 핵 공격 버튼을 유닛 깃발 위에 그려 클릭할 수 있게 합니다.", pl_PL = "Przyciski ataku miast i dzielnic wojskowych oraz przyciski ataku jądrowego silosów są rysowane nad flagami jednostek, gdzie można je kliknąć.", pt_BR = "Os botões de ataque das cidades e dos acampamentos, e os de ataque nuclear dos silos, são desenhados acima das bandeiras das unidades, onde continuam clicáveis.", ru_RU = "Кнопки атаки городов и военных лагерей, а также кнопки ядерного удара из шахт рисуются поверх флагов отрядов, где на них можно нажать.", zh_Hans_CN = "城市和军营的攻击按钮，以及发射井的核打击按钮，绘制在单位旗帜上方，保持可点击。" },
	LOC_BGD_OPT_UI_BOUTONS_NOM = { en_US = "Attack buttons above unit flags", fr_FR = "Boutons d'attaque au-dessus des drapeaux d'unités", de_DE = "Angriffsschaltflächen über den Einheitenflaggen", es_ES = "Botones de ataque sobre las banderas de unidades", it_IT = "Pulsanti di attacco sopra le bandiere delle unità", ja_JP = "ユニットの旗より手前に攻撃ボタン", ko_KR = "유닛 깃발 위의 공격 버튼", pl_PL = "Przyciski ataku nad flagami jednostek", pt_BR = "Botões de ataque acima das bandeiras das unidades", ru_RU = "Кнопки атаки поверх флагов отрядов", zh_Hans_CN = "攻击按钮显示在单位旗帜上方" },
	LOC_BGD_OPT_UI_CARTE_ENTIERE_AIDE = { en_US = "The minimap and the camera cover the whole map from the first turn, without placing map pins at the edges. Unexplored areas stay hidden. Purely local: no effect on other players in multiplayer.", fr_FR = "La minimap et la caméra couvrent toute la carte dès le premier tour, sans poser d'épingles aux bords. Les zones inexplorées restent cachées. Purement local : sans effet sur les autres joueurs en multijoueur.", de_DE = "Minikarte und Kamera umfassen ab der ersten Runde die ganze Karte, ohne Kartenmarkierungen an den Rändern. Unerforschte Gebiete bleiben verborgen. Rein lokal: keine Auswirkung auf andere Spieler im Mehrspielermodus.", es_ES = "El minimapa y la cámara abarcan todo el mapa desde el primer turno, sin colocar marcadores en los bordes. Las zonas inexploradas siguen ocultas. Solo local: sin efecto sobre los demás jugadores en multijugador.", it_IT = "La minimappa e la telecamera coprono l'intera mappa dal primo turno, senza piazzare segnalini ai bordi. Le zone inesplorate restano nascoste. Solo locale: nessun effetto sugli altri giocatori in multigiocatore.", ja_JP = "ミニマップとカメラが最初のターンからマップ全体を範囲にします。端にマップピンを置く必要はありません。未探索の地域は隠れたままです。ローカルのみ：マルチプレイで他のプレイヤーには影響しません。", ko_KR = "미니맵과 카메라가 첫 턴부터 지도 전체를 다룹니다. 가장자리에 지도 핀을 놓을 필요가 없습니다. 탐험하지 않은 지역은 계속 가려집니다. 로컬 전용: 멀티플레이에서 다른 플레이어에게 영향이 없습니다.", pl_PL = "Minimapa i kamera obejmują całą mapę od pierwszej tury, bez stawiania znaczników na krawędziach. Niezbadane obszary pozostają ukryte. Działa tylko lokalnie: bez wpływu na innych graczy w trybie wieloosobowym.", pt_BR = "O minimapa e a câmera cobrem o mapa inteiro desde o primeiro turno, sem colocar marcadores nas bordas. As áreas inexploradas continuam ocultas. Apenas local: sem efeito sobre os outros jogadores no multijogador.", ru_RU = "Миникарта и камера охватывают всю карту с первого хода, без меток по краям. Неисследованные области остаются скрытыми. Только локально: не влияет на других игроков в сетевой игре.", zh_Hans_CN = "小地图和镜头从第一回合起就覆盖整张地图，无需在边缘放置地图标记。未探索的区域仍然隐藏。仅限本地：在多人游戏中不影响其他玩家。" },
	LOC_BGD_OPT_UI_CARTE_ENTIERE_NOM = { en_US = "Whole map from the start", fr_FR = "Carte entière dès le début", de_DE = "Ganze Karte von Anfang an", es_ES = "Mapa completo desde el inicio", it_IT = "Mappa intera fin dall'inizio", ja_JP = "最初からマップ全体", ko_KR = "처음부터 지도 전체", pl_PL = "Cała mapa od początku", pt_BR = "Mapa inteiro desde o início", ru_RU = "Вся карта с самого начала", zh_Hans_CN = "从一开始显示整张地图" },
	LOC_BGD_OPT_UI_CHARGES_AIDE = { en_US = "Based on Better Builder Charges Tracking (wltk). The flag of a unit with charges (builder, military engineer, Roman legion…) shows them instead of promotions. Replaces the mod if it is active.", fr_FR = "D'après Better Builder Charges Tracking (wltk). Le drapeau d'une unité qui a des charges (bâtisseur, ingénieur militaire, légion romaine…) les montre à la place des promotions. Remplace le mod s'il est actif.", de_DE = "Nach Better Builder Charges Tracking (wltk). Die Flagge einer Einheit mit Ladungen (Handwerker, Militärpionier, Legion …) zeigt diese statt der Beförderungen. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Better Builder Charges Tracking (wltk). La bandera de una unidad con cargas (constructor, ingeniero militar, legión…) las muestra en lugar de los ascensos. Sustituye al mod si está activo.", it_IT = "Basato su Better Builder Charges Tracking (wltk). La bandiera di un'unità con cariche (costruttore, ingegnere militare, legione…) le mostra al posto delle promozioni. Sostituisce la mod se è attiva.", ja_JP = "Better Builder Charges Tracking (wltk) に基づきます。残り回数を持つユニット (労働者、工兵、レギオンなど) の旗に、昇進の代わりにそれを表示します。MOD が有効な場合はそれに置き換わります。", ko_KR = "Better Builder Charges Tracking(wltk) 기반. 건설력이 있는 유닛(건설자, 공병, 군단병 등)의 깃발에 진급 대신 건설력을 표시합니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Better Builder Charges Tracking (wltk). Flaga jednostki z ładunkami (budowniczy, inżynier wojskowy, legion…) pokazuje je zamiast awansów. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Better Builder Charges Tracking (wltk). A bandeira de uma unidade com cargas (construtor, engenheiro militar, legião…) as mostra no lugar das promoções. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Better Builder Charges Tracking (wltk). Флаг отряда с зарядами (строитель, военный инженер, легион…) показывает их вместо повышений. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Better Builder Charges Tracking（wltk）。有可用次数的单位（建造者、军事工程师、罗马军团……）的旗帜上显示次数，代替晋升。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_CHARGES_NOM = { en_US = "Builder charges on their flag", fr_FR = "Charges des bâtisseurs sur leur drapeau", de_DE = "Ladungen der Handwerker auf ihrer Flagge", es_ES = "Cargas de los constructores en su bandera", it_IT = "Cariche dei costruttori sulla loro bandiera", ja_JP = "労働者の残り回数を旗に表示", ko_KR = "깃발에 건설자 건설력 표시", pl_PL = "Ładunki budowniczych na ich fladze", pt_BR = "Cargas dos construtores na bandeira", ru_RU = "Заряды строителей на их флаге", zh_Hans_CN = "在旗帜上显示建造者次数" },
	LOC_BGD_OPT_UI_DIAG_ACCORDS_AIDE = { en_US = "Writes to Lua.log the deal proposals sent and received, and what the deal screen shows, to understand crossed deals between humans.", fr_FR = "Écrit dans Lua.log les propositions d'accord reçues et envoyées, et ce que montre l'écran d'accord, pour comprendre les accords croisés entre humains.", de_DE = "Schreibt in Lua.log die gesendeten und empfangenen Abkommensvorschläge und was der Abkommensbildschirm zeigt, um gekreuzte Abkommen zwischen Menschen zu verstehen.", es_ES = "Escribe en Lua.log las propuestas de acuerdo enviadas y recibidas, y lo que muestra la pantalla de acuerdo, para entender los acuerdos cruzados entre humanos.", it_IT = "Scrive in Lua.log le proposte di accordo inviate e ricevute, e ciò che mostra la schermata degli accordi, per capire gli accordi incrociati tra umani.", ja_JP = "送受信した取引の提案と取引画面の表示内容を Lua.log に書き込み、人間同士の取引の行き違いを調べます。", ko_KR = "보내고 받은 거래 제안과 거래 화면의 내용을 Lua.log에 기록해, 사람 사이의 엇갈린 거래를 분석합니다.", pl_PL = "Zapisuje w Lua.log wysłane i otrzymane propozycje umów oraz to, co pokazuje ekran umowy, aby zrozumieć krzyżujące się umowy między ludźmi.", pt_BR = "Escreve no Lua.log as propostas de acordo enviadas e recebidas, e o que a tela de acordo mostra, para entender os acordos cruzados entre humanos.", ru_RU = "Записывает в Lua.log отправленные и полученные предложения сделок и то, что показывает экран сделки, чтобы разобраться в перекрёстных сделках между людьми.", zh_Hans_CN = "将发送和收到的交易提议以及交易界面显示的内容写入 Lua.log，用于分析人类玩家之间交错的交易。" },
	LOC_BGD_OPT_UI_DIAG_ACCORDS_NOM = { en_US = "Diagnose deals between players", fr_FR = "Diagnostic des accords entre joueurs", de_DE = "Diagnose der Abkommen zwischen Spielern", es_ES = "Diagnóstico de los acuerdos entre jugadores", it_IT = "Diagnostica degli accordi tra giocatori", ja_JP = "プレイヤー間の取引の診断", ko_KR = "플레이어 간 거래 진단", pl_PL = "Diagnostyka umów między graczami", pt_BR = "Diagnóstico dos acordos entre jogadores", ru_RU = "Диагностика сделок между игроками", zh_Hans_CN = "玩家间交易诊断" },
	LOC_BGD_OPT_UI_EPINGLES_AIDE = { en_US = "Map pins and their list are no longer rebuilt when nothing changed: fewer slowdowns in multiplayer.", fr_FR = "Les épingles et leur liste ne sont plus reconstruites quand rien n'a changé : moins de ralentissements en multijoueur.", de_DE = "Kartenmarkierungen und ihre Liste werden nicht mehr neu aufgebaut, wenn sich nichts geändert hat: weniger Ruckler im Mehrspielermodus.", es_ES = "Los marcadores y su lista ya no se reconstruyen cuando nada ha cambiado: menos ralentizaciones en multijugador.", it_IT = "I segnalini e il loro elenco non vengono più ricostruiti quando nulla è cambiato: meno rallentamenti in multigiocatore.", ja_JP = "変化がないときはマップピンとその一覧を再構築しません。マルチプレイでの引っかかりが減ります。", ko_KR = "바뀐 것이 없으면 지도 핀과 그 목록을 다시 만들지 않습니다. 멀티플레이에서 끊김이 줄어듭니다.", pl_PL = "Znaczniki i ich lista nie są już przebudowywane, gdy nic się nie zmieniło: mniej spowolnień w trybie wieloosobowym.", pt_BR = "Os marcadores e sua lista não são mais reconstruídos quando nada mudou: menos travamentos no multijogador.", ru_RU = "Метки и их список больше не перестраиваются, если ничего не изменилось: меньше подтормаживаний в сетевой игре.", zh_Hans_CN = "没有变化时不再重建地图标记及其列表：减少多人游戏中的卡顿。" },
	LOC_BGD_OPT_UI_EPINGLES_NOM = { en_US = "Lighter map pins", fr_FR = "Épingles de carte allégées", de_DE = "Leichtere Kartenmarkierungen", es_ES = "Marcadores de mapa más ligeros", it_IT = "Segnalini della mappa più leggeri", ja_JP = "マップピンの軽量化", ko_KR = "가벼운 지도 핀", pl_PL = "Lżejsze znaczniki mapy", pt_BR = "Marcadores do mapa mais leves", ru_RU = "Облегчённые метки карты", zh_Hans_CN = "更轻量的地图标记" },
	LOC_BGD_OPT_UI_JOURNAL_AIDE = { en_US = "Writes each interface file read to the proxy log.", fr_FR = "Note chaque fichier d'interface lu dans le journal du proxy.", de_DE = "Schreibt jede gelesene Oberflächendatei in das Proxy-Protokoll.", es_ES = "Anota cada archivo de interfaz leído en el registro del proxy.", it_IT = "Annota ogni file d'interfaccia letto nel registro del proxy.", ja_JP = "読み込まれた各インターフェースファイルをプロキシのログに記録します。", ko_KR = "읽어 들인 각 인터페이스 파일을 프록시 로그에 기록합니다.", pl_PL = "Zapisuje każdy wczytany plik interfejsu w dzienniku proxy.", pt_BR = "Anota cada arquivo de interface lido no registro do proxy.", ru_RU = "Записывает в журнал прокси каждый прочитанный файл интерфейса.", zh_Hans_CN = "将读取的每个界面文件记入代理日志。" },
	LOC_BGD_OPT_UI_JOURNAL_NOM = { en_US = "Log loaded scripts and XML", fr_FR = "Journal des scripts et XML chargés", de_DE = "Geladene Skripte und XML protokollieren", es_ES = "Registrar los scripts y XML cargados", it_IT = "Registra script e XML caricati", ja_JP = "読み込んだスクリプトと XML を記録", ko_KR = "불러온 스크립트와 XML 기록", pl_PL = "Zapisuj wczytane skrypty i XML", pt_BR = "Registrar os scripts e XML carregados", ru_RU = "Журнал загруженных скриптов и XML", zh_Hans_CN = "记录已加载的脚本和 XML" },
	LOC_BGD_OPT_UI_MERVEILLES_AIDE = { en_US = "A wonder removed from the production queue by a swap is put back, through normal game commands: no desync, even against players without the proxy.", fr_FR = "Une merveille retirée de la file de production par un échange y est remise, par des commandes normales du jeu : pas de désynchronisation, même face à des joueurs sans proxy.", de_DE = "Ein Weltwunder, das durch einen Tausch aus der Produktionswarteschlange entfernt wurde, wird mit normalen Spielbefehlen wieder eingereiht: keine Desynchronisation, auch gegen Spieler ohne Proxy.", es_ES = "Una maravilla retirada de la cola de producción por un intercambio se vuelve a poner, mediante órdenes normales del juego: sin desincronización, incluso contra jugadores sin el proxy.", it_IT = "Una meraviglia tolta dalla coda di produzione da uno scambio viene rimessa, tramite normali comandi del gioco: nessuna desincronizzazione, anche contro giocatori senza il proxy.", ja_JP = "入れ替えによって生産キューから外れた遺産を、通常のゲームコマンドで戻します。プロキシを持たないプレイヤーとも同期ずれは起きません。", ko_KR = "교체로 생산 대기열에서 빠진 불가사의를 일반 게임 명령으로 되돌립니다. 프록시가 없는 플레이어와도 동기화 오류가 생기지 않습니다.", pl_PL = "Cud usunięty z kolejki produkcji przez zamianę zostaje do niej przywrócony zwykłymi poleceniami gry: bez desynchronizacji, także z graczami bez proxy.", pt_BR = "Uma maravilha retirada da fila de produção por uma troca é recolocada, por meio de comandos normais do jogo: sem dessincronização, mesmo contra jogadores sem o proxy.", ru_RU = "Чудо, убранное из очереди производства перестановкой, возвращается в неё обычными командами игры: без рассинхронизации, даже с игроками без прокси.", zh_Hans_CN = "因交换而被移出生产队列的奇观，会通过正常的游戏指令放回：不会不同步，即使对方没有代理。" },
	LOC_BGD_OPT_UI_MERVEILLES_NOM = { en_US = "Wonder kept in the queue after a swap", fr_FR = "Merveille gardée dans la file après un échange", de_DE = "Weltwunder bleibt nach einem Tausch in der Warteschlange", es_ES = "Maravilla conservada en la cola tras un intercambio", it_IT = "Meraviglia mantenuta in coda dopo uno scambio", ja_JP = "入れ替え後も遺産をキューに残す", ko_KR = "교체 후에도 불가사의를 대기열에 유지", pl_PL = "Cud pozostaje w kolejce po zamianie", pt_BR = "Maravilha mantida na fila após uma troca", ru_RU = "Чудо остаётся в очереди после перестановки", zh_Hans_CN = "交换后奇观仍留在队列中" },
	LOC_BGD_OPT_UI_MESURE_EPINGLES_AIDE = { en_US = "Writes to Lua.log how long map pin and leader ribbon rebuilds take.", fr_FR = "Écrit dans Lua.log la durée des reconstructions d'épingles et du bandeau des dirigeants.", de_DE = "Schreibt in Lua.log, wie lange der Neuaufbau der Kartenmarkierungen und der Anführerleiste dauert.", es_ES = "Escribe en Lua.log cuánto tardan en reconstruirse los marcadores de mapa y la barra de líderes.", it_IT = "Scrive in Lua.log quanto durano le ricostruzioni dei segnalini della mappa e della barra dei leader.", ja_JP = "マップピンと指導者リボンの再構築にかかる時間を Lua.log に書き込みます。", ko_KR = "지도 핀과 지도자 리본을 다시 만드는 데 걸리는 시간을 Lua.log에 기록합니다.", pl_PL = "Zapisuje w Lua.log, ile trwa przebudowa znaczników mapy i paska przywódców.", pt_BR = "Escreve no Lua.log quanto tempo levam as reconstruções dos marcadores do mapa e da faixa de líderes.", ru_RU = "Записывает в Lua.log, сколько длится перестройка меток карты и ленты лидеров.", zh_Hans_CN = "将地图标记和领袖栏重建所需的时间写入 Lua.log。" },
	LOC_BGD_OPT_UI_MESURE_EPINGLES_NOM = { en_US = "Measure map pin cost", fr_FR = "Mesure du coût des épingles", de_DE = "Kosten der Kartenmarkierungen messen", es_ES = "Medir el coste de los marcadores", it_IT = "Misura il costo dei segnalini", ja_JP = "マップピンのコストを計測", ko_KR = "지도 핀 비용 측정", pl_PL = "Pomiar kosztu znaczników", pt_BR = "Medir o custo dos marcadores", ru_RU = "Измерение затрат на метки", zh_Hans_CN = "测量地图标记的开销" },
	LOC_BGD_OPT_UI_MESURE_MOUVEMENTS_AIDE = { en_US = "Writes to Lua.log how long the movement range of a unit standing on an enemy district takes to compute (BGD mouvements lines). Diagnostic only, on this machine.", fr_FR = "Écrit dans Lua.log le temps de calcul de la zone de déplacement d'une unité posée sur un quartier ennemi (lignes BGD mouvements). Diagnostic seulement, sur cette machine.", de_DE = "Schreibt in Lua.log, wie lange die Berechnung des Bewegungsbereichs einer Einheit auf einem feindlichen Bezirk dauert (Zeilen BGD mouvements). Nur zur Diagnose, auf diesem Rechner.", es_ES = "Escribe en Lua.log cuánto tarda en calcularse el área de movimiento de una unidad situada en un distrito enemigo (líneas BGD mouvements). Solo diagnóstico, en este equipo.", it_IT = "Scrive in Lua.log quanto tempo richiede il calcolo dell'area di movimento di un'unità su un distretto nemico (righe BGD mouvements). Solo diagnostica, su questo computer.", ja_JP = "敵の区域上にいるユニットの移動範囲の計算時間を Lua.log に書き込みます（BGD mouvements 行）。このマシンでの診断用のみ。", ko_KR = "적 특수지구 위에 있는 유닛의 이동 범위 계산 시간을 Lua.log에 기록합니다(BGD mouvements 줄). 이 컴퓨터에서의 진단 전용입니다.", pl_PL = "Zapisuje w Lua.log czas obliczania zasięgu ruchu jednostki stojącej na wrogiej dzielnicy (wiersze BGD mouvements). Tylko diagnostyka, na tym komputerze.", pt_BR = "Escreve no Lua.log quanto tempo leva para calcular a área de movimento de uma unidade sobre um distrito inimigo (linhas BGD mouvements). Apenas diagnóstico, nesta máquina.", ru_RU = "Записывает в Lua.log время расчёта зоны перемещения отряда, стоящего на вражеском районе (строки BGD mouvements). Только для диагностики, на этом компьютере.", zh_Hans_CN = "在 Lua.log 中记录位于敌方区域上的单位计算移动范围所需的时间（BGD mouvements 行）。仅用于诊断，仅限本机。" },
	LOC_BGD_OPT_UI_MESURE_MOUVEMENTS_NOM = { en_US = "Measure movement range cost", fr_FR = "Mesure du coût de la zone de déplacement", de_DE = "Kosten des Bewegungsbereichs messen", es_ES = "Medir el coste del área de movimiento", it_IT = "Misura il costo dell'area di movimento", ja_JP = "移動範囲の計算コストを計測", ko_KR = "이동 범위 계산 비용 측정", pl_PL = "Pomiar kosztu zasięgu ruchu", pt_BR = "Medir o custo da área de movimento", ru_RU = "Измерение затрат на зону перемещения", zh_Hans_CN = "测量移动范围的计算开销" },
	LOC_BGD_OPT_UI_NOTIFICATIONS_AIDE = { en_US = "Based on NotificationClear (336tarot). A button in the notification panel dismisses in one click those you can dismiss yourself. Replaces the mod if it is active.", fr_FR = "D'après NotificationClear (336tarot). Un bouton du panneau des notifications ferme d'un clic celles qu'on peut fermer soi-même. Remplace le mod s'il est actif.", de_DE = "Nach NotificationClear (336tarot). Eine Schaltfläche im Benachrichtigungsbereich schließt mit einem Klick alle, die Sie selbst schließen können. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en NotificationClear (336tarot). Un botón del panel de notificaciones cierra de un clic las que puedes cerrar tú mismo. Sustituye al mod si está activo.", it_IT = "Basato su NotificationClear (336tarot). Un pulsante del pannello delle notifiche chiude con un clic quelle che puoi chiudere da solo. Sostituisce la mod se è attiva.", ja_JP = "NotificationClear (336tarot) に基づきます。通知パネルのボタンで、自分で閉じられる通知をワンクリックで閉じます。MOD が有効な場合はそれに置き換わります。", ko_KR = "NotificationClear(336tarot) 기반. 알림 패널의 버튼으로 직접 닫을 수 있는 알림을 한 번에 닫습니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie NotificationClear (336tarot). Przycisk w panelu powiadomień zamyka jednym kliknięciem te, które możesz zamknąć sam. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em NotificationClear (336tarot). Um botão do painel de notificações fecha com um clique aquelas que você pode fechar sozinho. Substitui o mod se ele estiver ativo.", ru_RU = "На основе NotificationClear (336tarot). Кнопка на панели уведомлений одним щелчком закрывает те, которые вы можете закрыть сами. Заменяет мод, если он включён.", zh_Hans_CN = "基于 NotificationClear（336tarot）。通知面板中的按钮可一键关闭所有你能自行关闭的通知。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_NOTIFICATIONS_NOM = { en_US = "Clear notifications button", fr_FR = "Bouton d'effacement des notifications", de_DE = "Schaltfläche zum Löschen der Benachrichtigungen", es_ES = "Botón para borrar las notificaciones", it_IT = "Pulsante per cancellare le notifiche", ja_JP = "通知を消去するボタン", ko_KR = "알림 지우기 버튼", pl_PL = "Przycisk czyszczenia powiadomień", pt_BR = "Botão para limpar as notificações", ru_RU = "Кнопка очистки уведомлений", zh_Hans_CN = "清除通知按钮" },
	LOC_BGD_OPT_UI_POLITIQUES_AIDE = { en_US = "Based on Extended Policy Cards (Aristos). Each card shows its numeric gain for your empire, computed by Real Modifier Analysis (Infixo), fixed (Raj, Medina Quarter, Monasticism, Civil Prestige, maintenance cards, food on great person cards). No longer needs Better Report Screen. Replaces the mod if it is active.", fr_FR = "D'après Extended Policy Cards (Aristos). Chaque carte montre son gain chiffré pour votre empire, calculé par Real Modifier Analysis (Infixo), corrigé (Raj, Médina, Monachisme, Prestige civil, cartes d'entretien, nourriture des cartes de personnages illustres). Ne demande plus Better Report Screen. Remplace le mod s'il est actif.", de_DE = "Nach Extended Policy Cards (Aristos). Jede Karte zeigt ihren bezifferten Gewinn für Ihr Reich, berechnet von Real Modifier Analysis (Infixo), korrigiert (Raj, Medina-Viertel, Mönchtum, Ziviles Prestige, Unterhaltskarten, Nahrung der Karten für Große Persönlichkeiten). Benötigt Better Report Screen nicht mehr. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Extended Policy Cards (Aristos). Cada carta muestra su ganancia numérica para tu imperio, calculada por Real Modifier Analysis (Infixo), corregida (Raj, Medina, Monacato, Prestigio civil, cartas de mantenimiento, comida de las cartas de grandes personajes). Ya no necesita Better Report Screen. Sustituye al mod si está activo.", it_IT = "Basato su Extended Policy Cards (Aristos). Ogni carta mostra il suo guadagno in cifre per il tuo impero, calcolato da Real Modifier Analysis (Infixo), corretto (Raj, Quartiere della Medina, Monachesimo, Prestigio civile, carte di mantenimento, cibo delle carte dei grandi personaggi). Non richiede più Better Report Screen. Sostituisce la mod se è attiva.", ja_JP = "Extended Policy Cards (Aristos) に基づきます。各カードに、帝国にとっての効果を数値で表示します。計算は Real Modifier Analysis (Infixo) を修正したもの (ラージ、メディナ地区、修道制、市民の威信、維持費カード、偉人カードの食料) です。Better Report Screen は不要になりました。MOD が有効な場合はそれに置き換わります。", ko_KR = "Extended Policy Cards(Aristos) 기반. 각 카드에 제국에 대한 효과를 수치로 표시하며, Real Modifier Analysis(Infixo)를 수정해 계산합니다(영국 식민 통치, 메디나 지구, 수도원주의, 시민의 위신, 유지비 카드, 위인 카드의 식량). 더 이상 Better Report Screen이 필요하지 않습니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Extended Policy Cards (Aristos). Każda karta pokazuje swój liczbowy zysk dla twojego imperium, obliczony przez Real Modifier Analysis (Infixo), poprawiony (Zwierzchnictwo, Medyna, Monastycyzm, Prestiż obywatelski, karty utrzymania, żywność z kart wielkich ludzi). Nie wymaga już Better Report Screen. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Extended Policy Cards (Aristos). Cada cartão mostra o seu ganho numérico para o seu império, calculado pelo Real Modifier Analysis (Infixo), corrigido (Raj, Almedina, Monasticismo, Prestígio civil, cartões de manutenção, comida dos cartões de grandes personalidades). Não precisa mais do Better Report Screen. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Extended Policy Cards (Aristos). Каждая карточка показывает свою выгоду для вашей империи в цифрах, рассчитанную Real Modifier Analysis (Infixo) с исправлениями (Британская Индия, Квартал Медины, Монашество, Гражданский престиж, карточки содержания, пища на карточках великих людей). Better Report Screen больше не нужен. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Extended Policy Cards（Aristos）。每张卡显示其对你帝国的数值收益，由修正后的 Real Modifier Analysis（Infixo）计算（统治、古老城区、修道主义、公民威望、维护费卡、伟人卡的食物）。不再需要 Better Report Screen。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_POLITIQUES_NOM = { en_US = "Policy card effects", fr_FR = "Effet des cartes de politique", de_DE = "Wirkung der Politikkarten", es_ES = "Efecto de las cartas de política", it_IT = "Effetto delle carte politica", ja_JP = "政策カードの効果", ko_KR = "정책 카드 효과", pl_PL = "Efekt kart doktryn", pt_BR = "Efeito dos cartões de política", ru_RU = "Эффект карточек политики", zh_Hans_CN = "政策卡效果" },
	LOC_BGD_OPT_UI_RAPPORTS_AIDE = { en_US = "Based on Better Report Screen (Infixo). Reworked report screen, with Deals, Units, Policies, City-States and Cities tabs, and the effect of each policy and city-state, fixed like the cards. Replaces the mod if it is active.", fr_FR = "D'après Better Report Screen (Infixo). Écran des rapports refait, avec les onglets Accords, Unités, Politiques, Cités-États et Villes, et l'effet de chaque politique et cité-État, corrigé comme les cartes. Remplace le mod s'il est actif.", de_DE = "Nach Better Report Screen (Infixo). Überarbeiteter Berichtsbildschirm mit den Reitern Abkommen, Einheiten, Politiken, Stadtstaaten und Städte sowie der Wirkung jeder Politik und jedes Stadtstaats, korrigiert wie die Karten. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Better Report Screen (Infixo). Pantalla de informes rehecha, con las pestañas Acuerdos, Unidades, Políticas, Ciudades-estado y Ciudades, y el efecto de cada política y ciudad-estado, corregido como las cartas. Sustituye al mod si está activo.", it_IT = "Basato su Better Report Screen (Infixo). Schermata dei rapporti rifatta, con le schede Accordi, Unità, Politiche, Città-stato e Città, e l'effetto di ogni politica e città-stato, corretto come le carte. Sostituisce la mod se è attiva.", ja_JP = "Better Report Screen (Infixo) に基づきます。取引、ユニット、政策、都市国家、都市のタブを持つ新しいレポート画面で、各政策と都市国家の効果をカードと同じく修正して表示します。MOD が有効な場合はそれに置き換わります。", ko_KR = "Better Report Screen(Infixo) 기반. 거래, 유닛, 정책, 도시국가, 도시 탭이 있는 새 보고서 화면으로, 각 정책과 도시국가의 효과를 카드와 같이 수정해 보여 줍니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Better Report Screen (Infixo). Przebudowany ekran raportów z kartami Umowy, Jednostki, Doktryny, Miasta-państwa i Miasta oraz efektem każdej doktryny i miasta-państwa, poprawionym jak w kartach. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Better Report Screen (Infixo). Tela de relatórios refeita, com as abas Acordos, Unidades, Políticas, Cidades-estado e Cidades, e o efeito de cada política e cidade-estado, corrigido como os cartões. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Better Report Screen (Infixo). Переработанный экран отчётов с вкладками «Сделки», «Отряды», «Политика», «Города-государства» и «Города» и эффектом каждой политики и города-государства, исправленным, как на карточках. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Better Report Screen（Infixo）。重做的报告界面，含交易、单位、政策、城邦和城市标签页，并显示每项政策和每个城邦的效果，与政策卡一样经过修正。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_RAPPORTS_NOM = { en_US = "Better report screen", fr_FR = "Écran des rapports amélioré", de_DE = "Verbesserter Berichtsbildschirm", es_ES = "Pantalla de informes mejorada", it_IT = "Schermata dei rapporti migliorata", ja_JP = "改良されたレポート画面", ko_KR = "개선된 보고서 화면", pl_PL = "Ulepszony ekran raportów", pt_BR = "Tela de relatórios melhorada", ru_RU = "Улучшенный экран отчётов", zh_Hans_CN = "改进的报告界面" },
	LOC_BGD_OPT_UI_RECENTRAGE_AIDE = { en_US = "Original game behavior: the camera recenters on the city when an attack button is clicked.", fr_FR = "Comportement d'origine du jeu : la caméra se recentre sur la ville au clic sur un bouton d'attaque.", de_DE = "Ursprüngliches Verhalten des Spiels: Die Kamera zentriert sich beim Klick auf eine Angriffsschaltfläche auf die Stadt.", es_ES = "Comportamiento original del juego: la cámara se centra en la ciudad al pulsar un botón de ataque.", it_IT = "Comportamento originale del gioco: la visuale si centra sulla città al clic su un pulsante di attacco.", ja_JP = "ゲーム本来の動作: 攻撃ボタンをクリックするとカメラが都市に移動します。", ko_KR = "게임 원래 동작: 공격 버튼을 클릭하면 카메라가 도시로 이동합니다.", pl_PL = "Oryginalne zachowanie gry: po kliknięciu przycisku ataku kamera centruje się na mieście.", pt_BR = "Comportamento original do jogo: a câmera centraliza na cidade ao clicar num botão de ataque.", ru_RU = "Исходное поведение игры: при нажатии кнопки атаки камера центрируется на городе.", zh_Hans_CN = "游戏原本的行为：点击攻击按钮时镜头会移到城市。" },
	LOC_BGD_OPT_UI_RECENTRAGE_NOM = { en_US = "Recenter the camera when clicking these buttons", fr_FR = "Recentrer la caméra au clic sur ces boutons", de_DE = "Kamera beim Klick auf diese Schaltflächen zentrieren", es_ES = "Centrar la cámara al pulsar estos botones", it_IT = "Centra la visuale al clic su questi pulsanti", ja_JP = "これらのボタンのクリック時にカメラを移動", ko_KR = "이 버튼을 클릭하면 카메라 이동", pl_PL = "Centruj kamerę po kliknięciu tych przycisków", pt_BR = "Centralizar a câmera ao clicar nesses botões", ru_RU = "Центрировать камеру при нажатии этих кнопок", zh_Hans_CN = "点击这些按钮时移动镜头" },
	LOC_BGD_OPT_UI_RENDEMENTS_AIDE = { en_US = "The top bar updates after a governor title, a governor move or a great person, without changing a citizen. Display only: no desync.", fr_FR = "Le bandeau du haut se met à jour après un titre de gouverneur, un déplacement de gouverneur ou un personnage illustre, sans changer un citoyen. Affichage seulement : pas de désynchronisation.", de_DE = "Die obere Leiste aktualisiert sich nach einem Gouverneurstitel, einer Gouverneursversetzung oder einer Großen Persönlichkeit, ohne einen Bürger zu verschieben. Nur Anzeige: keine Desynchronisation.", es_ES = "La barra superior se actualiza tras un título de gobernador, un traslado de gobernador o un gran personaje, sin mover a ningún ciudadano. Solo visualización: sin desincronización.", it_IT = "La barra superiore si aggiorna dopo un titolo di governatore, uno spostamento di governatore o un grande personaggio, senza spostare un cittadino. Solo visualizzazione: nessuna desincronizzazione.", ja_JP = "総督の称号、総督の移動、偉人の後に、市民を動かさなくても上部バーが更新されます。表示のみで、同期ずれは起きません。", ko_KR = "총독 칭호, 총독 이동, 위인 이후에 시민을 옮기지 않아도 상단 바가 갱신됩니다. 표시만 바뀌며 동기화 오류는 없습니다.", pl_PL = "Górny pasek odświeża się po tytule gubernatora, przeniesieniu gubernatora lub wielkim człowieku, bez przestawiania obywatela. Tylko wyświetlanie: bez desynchronizacji.", pt_BR = "A barra superior é atualizada após um título de governador, uma transferência de governador ou uma grande personalidade, sem mexer num cidadão. Apenas exibição: sem dessincronização.", ru_RU = "Верхняя панель обновляется после звания губернатора, перевода губернатора или великого человека, без перестановки жителя. Только отображение: без рассинхронизации.", zh_Hans_CN = "在总督头衔、总督调任或伟人之后，无需调整公民，顶部栏也会更新。仅影响显示：不会不同步。" },
	LOC_BGD_OPT_UI_RENDEMENTS_NOM = { en_US = "Empire yields updated after a governor or great person", fr_FR = "Rendements d'empire à jour après un gouverneur ou un personnage illustre", de_DE = "Reichserträge nach Gouverneur oder Großer Persönlichkeit aktuell", es_ES = "Rendimientos del imperio actualizados tras un gobernador o un gran personaje", it_IT = "Rese dell'impero aggiornate dopo un governatore o un grande personaggio", ja_JP = "総督や偉人の後に帝国の産出量を更新", ko_KR = "총독이나 위인 이후 제국 산출량 갱신", pl_PL = "Aktualne plony imperium po gubernatorze lub wielkim człowieku", pt_BR = "Rendimentos do império atualizados após um governador ou uma grande personalidade", ru_RU = "Доходы империи обновляются после губернатора или великого человека", zh_Hans_CN = "总督或伟人之后更新帝国产出" },
	LOC_BGD_OPT_UI_ROUTES_AIDE = { en_US = "The flag of each of your traders on a route shows the number of turns until its trade route ends. The trader then finishes it on returning to its origin city. Display only.", fr_FR = "Le drapeau de chacun de vos négociants en route montre le nombre de tours avant la fin de sa route commerciale. Le négociant la termine ensuite en rentrant à sa ville d'origine. Affichage seulement.", de_DE = "Die Flagge jedes Ihrer Händler auf einem Handelsweg zeigt die Runden bis zum Ende des Handelswegs. Der Händler beendet ihn dann bei der Rückkehr in seine Heimatstadt. Nur Anzeige.", es_ES = "La bandera de cada uno de tus comerciantes en ruta muestra los turnos que faltan para que termine su ruta comercial. Después, el comerciante la termina al volver a su ciudad de origen. Solo visualización.", it_IT = "La bandiera di ciascuno dei tuoi commercianti in viaggio mostra il numero di turni prima della fine della sua rotta commerciale. Il commerciante la conclude poi tornando alla sua città d'origine. Solo visualizzazione.", ja_JP = "交易中の各交易商の旗に、交易路が終わるまでのターン数を表示します。交易商はその後、出発都市に戻った時点で交易路を終えます。表示のみ。", ko_KR = "교역 중인 각 상인의 깃발에 교역로가 끝날 때까지 남은 턴 수를 표시합니다. 상인은 그 뒤 출발 도시로 돌아오면서 교역로를 마칩니다. 표시만 바뀝니다.", pl_PL = "Flaga każdego twojego kupca w drodze pokazuje liczbę tur do końca jego szlaku handlowego. Kupiec kończy go potem po powrocie do miasta pochodzenia. Tylko wyświetlanie.", pt_BR = "A bandeira de cada um dos seus comerciantes em rota mostra o número de turnos até o fim da rota comercial. O comerciante a termina depois, ao voltar para a cidade de origem. Apenas exibição.", ru_RU = "Флаг каждого вашего торговца в пути показывает число ходов до конца его торгового пути. Затем торговец завершает его, вернувшись в родной город. Только отображение.", zh_Hans_CN = "你每个正在运营路线的商人旗帜上，显示其贸易路线结束前的回合数。之后商人回到出发城市时结束该路线。仅影响显示。" },
	LOC_BGD_OPT_UI_ROUTES_NOM = { en_US = "Trade route turns remaining", fr_FR = "Tours restants des routes commerciales", de_DE = "Verbleibende Runden der Handelswege", es_ES = "Turnos restantes de las rutas comerciales", it_IT = "Turni rimanenti delle rotte commerciali", ja_JP = "交易路の残りターン", ko_KR = "교역로 남은 턴", pl_PL = "Pozostałe tury szlaków handlowych", pt_BR = "Turnos restantes das rotas comerciais", ru_RU = "Оставшиеся ходы торговых путей", zh_Hans_CN = "贸易路线剩余回合" },
