	LOC_BGD_OPT_VERIF_MAJ_AIDE = { en_US = "When the game starts, looks on GitHub for a new version of BetterGameExperience, and offers it in the main menu. Takes effect the next time the game starts.", fr_FR = "Au lancement du jeu, cherche sur GitHub une nouvelle version de BetterGameExperience, et la propose au menu principal. Prend effet au prochain lancement du jeu.", de_DE = "Sucht beim Spielstart auf GitHub nach einer neuen Version von BetterGameExperience und bietet sie im Hauptmenü an. Wirkt beim nächsten Spielstart.", es_ES = "Al iniciar el juego, busca en GitHub una nueva versión de BetterGameExperience y la ofrece en el menú principal. Surte efecto la próxima vez que se inicie el juego.", it_IT = "All'avvio del gioco, cerca su GitHub una nuova versione di BetterGameExperience e la propone nel menu principale. Ha effetto al prossimo avvio del gioco.", ja_JP = "ゲーム起動時に GitHub で BetterGameExperience の新しいバージョンを探し、メインメニューで案内します。次回のゲーム起動時から有効です。", ko_KR = "게임을 시작할 때 GitHub에서 BetterGameExperience의 새 버전을 찾아 메인 메뉴에서 알려 줍니다. 다음에 게임을 시작할 때부터 적용됩니다.", pl_PL = "Przy uruchomieniu gry szuka w serwisie GitHub nowej wersji BetterGameExperience i proponuje ją w menu głównym. Działa od następnego uruchomienia gry.", pt_BR = "Ao iniciar o jogo, procura no GitHub uma nova versão do BetterGameExperience e a oferece no menu principal. Vale a partir da próxima vez que o jogo for iniciado.", ru_RU = "При запуске игры ищет на GitHub новую версию BetterGameExperience и предлагает её в главном меню. Действует со следующего запуска игры.", zh_Hans_CN = "游戏启动时在 GitHub 上查找 BetterGameExperience 的新版本，并在主菜单中提示。下次启动游戏时生效。" },
	LOC_BGD_OPT_VERIF_MAJ_NOM = { en_US = "Check for updates", fr_FR = "Recherche des mises à jour", de_DE = "Nach Updates suchen", es_ES = "Buscar actualizaciones", it_IT = "Cerca aggiornamenti", ja_JP = "アップデートを確認", ko_KR = "업데이트 확인", pl_PL = "Sprawdzaj aktualizacje", pt_BR = "Procurar atualizações", ru_RU = "Проверять обновления", zh_Hans_CN = "检查更新" },
