	LOC_BGD_OPT_WMD_ACCEL_NOM = { en_US = "Nuclear strike animation speed-up", fr_FR = "Accélération de l'animation des armes nucléaires", de_DE = "Beschleunigte Animation von Atomschlägen", es_ES = "Animación acelerada de los ataques nucleares", it_IT = "Animazione accelerata degli attacchi nucleari", ja_JP = "核攻撃アニメーションの高速化", ko_KR = "핵 공격 애니메이션 가속", pl_PL = "Przyspieszona animacja ataków jądrowych", pt_BR = "Animação acelerada dos ataques nucleares", ru_RU = "Ускорение анимации ядерных ударов", zh_Hans_CN = "加速核打击动画" },
